        .to.include("application/json");
});

pm.test("Usuário deve ser criado mesmo com e-mail inválido", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("id");
    pm.expect(response.email).to.eql("email-invalido");
});

pm.test("E-mail retornado deve permanecer com o valor enviado", function () {
    const response = pm.response.json();

    pm.expect(response.email).to.eql("email-invalido");
});

pm.test("Resposta deve manter os demais dados enviados", function () {
    const response = pm.response.json();

    pm.expect(response.firstName).to.eql("Felipe");
    pm.expect(response.lastName).to.eql("QA");
    pm.expect(response.age).to.eql(33);
    pm.expect(response.username).to.eql("felipeqa_invalid");
});

pm.test("Tempo de resposta deve ser menor que 2500ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2500);
});

